import sys
import csv
import json


def normalize_item(name):
    # collapse all whitespace to single spaces and casefold
    return " ".join(name.split()).casefold()


def main():
    filename = sys.argv[1]
    merges = {}

    with open(filename, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print(json.dumps([]))
            return

        try:
            item_idx = header.index('item')
            qty_idx = header.index('quantity')
        except ValueError:
            print(json.dumps([]))
            return

        for row in reader:
            if len(row) <= max(item_idx, qty_idx):
                continue

            item = normalize_item(row[item_idx])
            if not item:
                continue

            qty_raw = row[qty_idx]
            if qty_raw.strip() == '':
                qty = 1
            else:
                try:
                    qty = int(qty_raw.strip(), 10)
                except ValueError:
                    continue
                if qty < 0:
                    continue

            merges[item] = merges.get(item, 0) + qty

    result = [{"item": k, "quantity": merges[k]} for k in sorted(merges.keys())]
    print(json.dumps(result))


if __name__ == '__main__':
    main()
